<script setup lang="ts">
const confirm=window.confirm.bind(window);
import { computed,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { state,run,queueDraft,send,pendingItem,prepare,rebase,adoptServer,assignmentFor } from '../store';import { exportJson } from '../storage/export';
const router=useRouter(),route=useRoute(),draft=computed(()=>state.drafts.find(d=>d.key===route.params.key)),review=ref(false),accepted=ref(false);
const queued=computed(()=>draft.value?pendingItem(draft.value):undefined);
// Return only after acknowledgement; failed uploads and newer edits stay here.
watch(()=>draft.value?.sync,(sync,previous)=>{if(sync==='synced'&&previous==='uploading')void router.replace('/')});
const server=computed(()=>state.cache?.sessions.find(s=>s.id===draft.value?.serverId));
async function finish(){const d=draft.value!;const absent=d.students.filter(w=>!w.evaluated_at).map(w=>w.name);if(!confirm(absent.length?`سيسجل الطلاب التالية أسماؤهم غائبين:\n${absent.join('، ')}\nهل تريد إنهاء الحصة وتجهيزها للإرسال؟`:'هل تريد إنهاء الحصة وتجهيزها للإرسال؟'))return;await run(async()=>{await queueDraft(d);state.message=state.online?'الحصة جاهزة وسيتم إرسالها تلقائيًا.':'ستُرسل الحصة عند عودة الاتصال؛ أبقِ الصفحة مفتوحة.'})}
async function inspect(){await run(async()=>{await prepare();review.value=true;accepted.value=false})}
function download(){if(draft.value)exportJson('halaka-session.json',draft.value)}
</script>
<template><section v-if="draft" class="roster-page"><RouterLink to="/" class="back roster-back"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg>الحصص</RouterLink><div class="session-toolbar"><div class="page-title roster-heading"><div class="roster-title"><h1>{{state.cache?.groups.find(g=>g.id===draft!.group_id)?.name||'الحصة'}}</h1><div class="roster-datetime"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18"/></svg><time :datetime="draft.timestamp">{{new Date(draft.timestamp).toLocaleDateString('ar',{day:'numeric',month:'short',year:'numeric'})}}<span class="roster-time">{{new Date(draft.timestamp).toLocaleTimeString('ar',{hour:'numeric',minute:'2-digit'})}}</span></time></div></div><RouterLink class="quiet roster-edit" aria-label="تعديل الحصة" :to="`/session/${draft.key}/edit`"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 4 5 5M4 20l5-1L20 8a3.5 3.5 0 0 0-5-5L4 14Z"/></svg>تعديل</RouterLink></div><div class="session-toolbar-actions"><button v-if="!queued" class="primary" :disabled="state.busy" @click="finish">{{draft.serverId?'إنهاء وإرسال التعديلات':'إنهاء الحصة وإرسالها'}}</button><button v-else-if="queued.state!=='conflict'" class="primary" :disabled="state.busy||!state.online" @click="run(()=>send(draft!))">{{state.busy?'جارٍ الإرسال…':'إرسال الآن'}}</button><button v-else class="primary" :disabled="state.busy||!state.online" @click="inspect">مراجعة الحصة قبل الإرسال</button></div></div><div class="between section-heading"><h2>الطلاب</h2><span class="muted">تم تسجيل {{draft.students.filter(s=>s.evaluated_at).length}} من {{draft.students.length}}</span></div><div class="student-list"><RouterLink v-for="(w,index) in draft.students" :key="w.student_id" class="student-row" :class="w.evaluated_at?'student-recorded':w.attendance_status==='absent'?'student-absent':'student-pending'" :to="`/session/${draft.key}/student/${w.student_id}`"><span class="avatar">{{index+1}}</span><span class="student-info"><strong>{{w.name}}</strong><small class="student-evaluation-status" :class="w.evaluated_at?'green':'muted'">{{w.evaluated_at?'تم التسجيل ✓':w.attendance_status==='absent'?'غائب':'لم يُقيَّم بعد'}}</small></span><span v-if="w.archived" class="badge">مؤرشف</span><span class="chevron">‹</span></RouterLink></div><div class="session-submit"><p v-if="draft.lastError" class="notice error">{{draft.lastError}}</p><template v-if="queued"><p class="muted">سيُعاد الإرسال تلقائيًا عند استقرار الاتصال. أبقِ الصفحة مفتوحة حتى تأكيد النجاح.</p><button v-if="queued.state!=='conflict'" class="quiet" :disabled="state.busy||!state.online" @click="run(prepare)">تجهيز البيانات</button><button v-else class="primary" :disabled="state.busy||!state.online" @click="inspect">تحديث البيانات ومراجعة التعارض</button></template><template v-else><p v-if="draft.sync==='synced'" class="success-text">تم إرسال النسخة المحفوظة ✓</p><button v-if="draft.sync!=='synced'" class="quiet" :disabled="state.busy||!state.online" @click="inspect">مراجعة النسخة الحالية قبل الإرسال</button></template></div>
 <section v-if="review" class="card review"><h2>مراجعة البيانات الحالية</h2><p>لن يُستبدل عملك تلقائيًا. قارن النسختين قبل اختيار ما تريد اعتماده.</p><div class="comparison"><div><h3>عملك على الجهاز</h3><p>{{new Date(draft.timestamp).toLocaleString('ar')}}</p><article v-for="w in draft.students" :key="w.student_id"><strong>{{w.name}} · {{w.evaluated_at?'حاضر':'غائب'}}</strong><p v-for="(a,i) in w.assessments" :key="i">{{assignmentFor(draft,w,a.quran_assignment_id,a.assignment_client_uuid)?.surah_name||'واجب غير متاح'}}: {{a.grade===''?'دون علامة':a.grade}}<br>{{a.comment}}</p><p v-for="(a,i) in w.assignments" :key="'a'+i">{{a.surah_name}} {{a.from_ayah}}–{{a.to_ayah}} · {{a.is_passed?'مجتاز':'قيد الإنجاز'}}</p><p v-if="w.removed_assignment_ids.length">حذف {{w.removed_assignment_ids.length}} واجب غير مقيم</p></article></div><div><h3>النسخة الحالية على الخادم</h3><template v-if="server"><p>{{new Date(server.timestamp).toLocaleString('ar')}}</p><article v-for="w in server.students" :key="w.student_id"><strong>{{w.name}} · {{w.evaluated_at?'حاضر':'غائب'}}</strong><p v-for="(a,i) in w.assessments" :key="i">{{assignmentFor(draft,w,a.quran_assignment_id)?.surah_name||'واجب مؤرشف'}}: {{a.grade}}<br>{{a.comment}}</p><p v-for="a in state.cache?.assignments[w.student_id]||[]" :key="a.id">{{a.surah_name}} {{a.from_ayah}}–{{a.to_ayah}} · {{a.is_passed?'مجتاز':'قيد الإنجاز'}}</p></article></template><p v-else>{{draft.serverId?'الحصة غير متاحة أو مؤرشفة.':'حصة جديدة لم تُرسل بعد.'}}</p></div></div><label class="check"><input v-model="accepted" type="checkbox">راجعت الفروق وأريد تطبيق عملي المحلي فوق القيم الحالية.</label><button class="primary" :disabled="!accepted||state.busy" @click="run(async()=>{await rebase(draft!);review=false})">اعتماد عملي بعد المراجعة</button><button v-if="server" class="quiet" @click="run(async()=>{if(confirm('هل تريد اعتماد نسخة الخادم؟ ستحتفظ حلقة بنسخة استرجاع من عملك المحلي.')){await adoptServer(draft!);review=false}})">اعتماد نسخة الخادم</button><button class="quiet" @click="download">تنزيل نسخة من عملي</button><p class="muted">قبل استبدال أي نسخة، تُحفظ نسخة استرجاع مؤقتة في هذه الصفحة في «حسابي».</p></section>
 </section><p v-else class="empty">هذه الحصة غير متاحة لهذا الحساب على الجهاز.</p></template>
